mapper.update:
UPDATE tbl_menu_review SET star_score = #{starScore}, review_text = #{reviewText}, updatedate = SYSDATE
WHERE review_id = #{reviewId} AND userid = #{userid}
	AND regdate >= TRUNC(SYSDATE) AND regdate < TRUNC(SYSDATE) + 1

UPDATE tbl_menu SET avg_rating = (
	SELECT NVL(ROUND(AVG(star_score), 2), 0) FROM tbl_menu_review WHERE menu_id = #{menuId}
) WHERE menu_id = #{menuId}
